import java.util.*;

class Solution {
    public int scoreOfParentheses(String s) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);                               // score of the outermost level
        for (char c : s.toCharArray()) {
            if (c == '(') {
                stack.push(0);                       // new level starts empty
            } else {
                int inner = stack.pop();
                int worth = Math.max(2 * inner, 1);  // "()" = 1, "(A)" = 2 * A
                stack.push(stack.pop() + worth);     // add to the enclosing level
            }
        }
        return stack.pop();
    }
}

