function scoreOfParentheses(s) {
  let depth = 0, ans = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === "(") depth++;
    else { depth--; if (s[i - 1] === "(") ans += 2 ** depth; }
  }
  return ans;
}
